//! CIRISEdge#930 — **a `FederationDirectory` that counts every call.**
//!
//! Test-only. Mechanically derived from persist's own
//! `federation/directory_double.rs` (`FaultInjectingDirectory`, generated by
//! persist's `scripts/gen_directory_double.py`) at the pinned tag v59.1.2:
//! the same delegations, each fault check replaced by a counter bump. It
//! wraps a REAL directory, so every call keeps real behaviour; a trait method
//! with a default body is not delegated and runs that default over the
//! counted required methods, so a composite read is counted as the reads it
//! is made of. The count is per METHOD NAME, independent of edge's own
//! bookkeeping: a witness that edge read less cannot be satisfied by edge
//! saying so.
//!
//! On a persist bump that adds a required trait method this file fails to
//! compile; regenerate it from the new pin the same way.

#![allow(clippy::all, clippy::pedantic, unused_imports)]

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

use ciris_persist::federation::*;

/// A [`FederationDirectory`] that delegates to `inner` and counts each call
/// by method name.
#[derive(Clone)]
pub(crate) struct CountingDirectory {
    inner: Arc<dyn FederationDirectory>,
    counts: Arc<Mutex<BTreeMap<&'static str, usize>>>,
}

impl CountingDirectory {
    pub(crate) fn new(inner: Arc<dyn FederationDirectory>) -> Self {
        Self {
            inner,
            counts: Arc::new(Mutex::new(BTreeMap::new())),
        }
    }

    fn hit(&self, method: &'static str) {
        *self
            .counts
            .lock()
            .expect("counts")
            .entry(method)
            .or_insert(0) += 1;
    }

    /// Every count so far.
    pub(crate) fn counts(&self) -> BTreeMap<&'static str, usize> {
        self.counts.lock().expect("counts").clone()
    }

    /// Calls to `method` so far.
    pub(crate) fn count(&self, method: &str) -> usize {
        self.counts
            .lock()
            .expect("counts")
            .get(method)
            .copied()
            .unwrap_or(0)
    }

    /// Every call so far, all methods.
    pub(crate) fn total(&self) -> usize {
        self.counts.lock().expect("counts").values().sum()
    }

    /// Forget the counts.
    pub(crate) fn reset(&self) {
        self.counts.lock().expect("counts").clear();
    }
}

